<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/AdministracaoTextos.php';
session_start();
require_once dirname(__DIR__) . DIRECTORY_SEPARATOR . 'classes' . DIRECTORY_SEPARATOR . 'UsuarioSessao.php';
if (empty($_SESSION['autenticado'])) { header('Location: ../index.php?erro=sessao_expirada'); exit; }
$config = [];
foreach (file(dirname(__DIR__) . DIRECTORY_SEPARATOR . '.env', FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) ?: [] as $line) {
    if (str_starts_with(trim($line), '#') || !str_contains($line, '=')) continue;
    [$key, $value] = explode('=', $line, 2); $config[trim($key)] ??= trim(trim($value), "\"'");
}
$pdo = new PDO('mysql:host=' . ($config['GPT_DB_HOST'] ?? '127.0.0.1') . ';port=' . ($config['GPT_DB_PORT'] ?? '3306') . ';dbname=' . $_SESSION['tenant']['banco_dados'] . ';charset=utf8mb4', $config['GPT_DB_USERNAME'] ?? '', $config['GPT_DB_PASSWORD'] ?? '', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
if (!UsuarioSessao::atualizar($pdo, $_SESSION) || ($_SESSION['usuario']['codigo_perfil'] ?? '') !== 'ADMINISTRADOR') { http_response_code(403); exit(adm_t('Acesso negado.')); }
function listaCall(PDO $pdo, string $sql, array $params = []): array { if (str_contains($sql, 'sp_crud_select') && str_contains($sql, 'NULL,25')) { $f = json_decode((string)($_GET['filtros'] ?? '{}'), true); if (isset($params['filtros']) && is_array($f)) $params['filtros'] = listaJson($f); $sql = str_replace('NULL,25', ':busca,25', $sql); $params['busca'] = trim((string)($_GET['busca'] ?? '')); } $statement = $pdo->prepare($sql); $statement->execute($params); $rows = $statement->fetchAll(); $statement->closeCursor(); return $rows; }
function listaJson(mixed $value): string { if (is_array($value) && (($value['status'] ?? '') === 'SOLICITADA')) { $value['filtros'] = json_encode((array)json_decode((string)($_POST['filtros'] ?? '{}'), true), JSON_UNESCAPED_UNICODE); $value['busca'] = trim((string)($_POST['busca'] ?? '')); $value['colunas'] = trim((string)($_POST['colunas'] ?? '[]')) ?: '[]'; } return json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); }
$uid = (int)$_SESSION['usuario']['codusuario'];
$isAjax = ($_SERVER['HTTP_X_REQUESTED_WITH'] ?? '') === 'XMLHttpRequest' || ($_POST['ajax'] ?? '') === '1';
if ($isAjax && ($_POST['action'] ?? '') === 'count_rows') { $f = json_decode((string)($_POST['filtros'] ?? '{}'), true); $c = listaCall($pdo, 'CALL sp_crud_count(:tabela,:filtros,:busca)', ['tabela' => 'vw_formulario_lista_grid', 'filtros' => listaJson(is_array($f) ? $f : []), 'busca' => trim((string)($_POST['busca'] ?? ''))]); header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok' => true, 'total' => (int)($c[0]['total_registros'] ?? 0)]); exit; }
if ($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='export_request') { require_once dirname(__DIR__).DIRECTORY_SEPARATOR.'classes'.DIRECTORY_SEPARATOR.'ExportacaoSolicitacao.php';$jobId=ExportacaoSolicitacao::solicitar($pdo,(int)$uid,'seguranca_lista','Listas');if($isAjax){header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>$jobId>0,'message'=>ExportacaoSolicitacao::mensagem()],JSON_UNESCAPED_UNICODE);exit;}}
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'save_preferences') {
    header('Content-Type: application/json; charset=utf-8');
    foreach ((array)json_decode((string)($_POST['preferences'] ?? '[]'), true) as $item) {
        $column = preg_replace('/[^a-zA-Z0-9_]/', '', (string)($item['coluna'] ?? '')); if (!$column) continue;
        $old = listaCall($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela' => 'vw_preferencias_grid', 'filtros' => listaJson(['codusuario' => $uid, 'transacao' => 'seguranca_lista', 'coluna' => $column])]);
        $data = ['codusuario' => $uid, 'transacao' => 'seguranca_lista', 'coluna' => $column, 'ordem' => (int)($item['ordem'] ?? 0), 'visivel' => (int)!empty($item['visivel']), 'largura' => max(60, (int)($item['largura'] ?? 140))];
        if ($old) listaCall($pdo, 'CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'preferencias_grid', 'chave' => listaJson(['codpreferenciagrid' => $old[0]['codpreferenciagrid']]), 'dados' => listaJson($data)]);
        else listaCall($pdo, 'CALL sp_crud_insert(:tabela,:dados)', ['tabela' => 'preferencias_grid', 'dados' => listaJson($data)]);
    }
    echo json_encode(['ok' => true]); exit;
}
if ($isAjax && ($_POST['action'] ?? '') === 'save_rows') {
    $created = [];
    foreach ((array)($_POST['rows'] ?? []) as $key => $row) {
        $data = ['codigo' => trim((string)($row['codigo'] ?? '')), 'label_pt' => trim((string)($row['label_pt'] ?? '')), 'label_en' => trim((string)($row['label_en'] ?? '')), 'label_es' => trim((string)($row['label_es'] ?? '')), 'descricao' => trim((string)($row['descricao'] ?? '')) ?: null, 'origem' => in_array(($row['origem'] ?? 'FIXA'), ['FIXA', 'BANCO'], true) ? $row['origem'] : 'FIXA', 'fonte_codigo' => trim((string)($row['fonte_codigo'] ?? '')) ?: null, 'campo_valor' => trim((string)($row['campo_valor'] ?? '')) ?: null, 'campo_label' => trim((string)($row['campo_label'] ?? '')) ?: null, 'filtro_json' => trim((string)($row['filtro_json'] ?? '')) ?: null, 'ativo' => !empty($row['ativo']) ? 1 : 0];
        if ($data['codigo'] === '' || $data['label_pt'] === '' || $data['label_en'] === '' || $data['label_es'] === '') continue;
        if (ctype_digit((string)$key)) listaCall($pdo, 'CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'formulario_lista', 'chave' => listaJson(['codformulariolista' => (int)$key]), 'dados' => listaJson($data)]);
        else { listaCall($pdo, 'CALL sp_crud_insert(:tabela,:dados)', ['tabela' => 'formulario_lista', 'dados' => listaJson($data)]); $found = listaCall($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela' => 'vw_formulario_lista_grid', 'filtros' => listaJson(['codigo' => $data['codigo']])]); if ($found) $created[(string)$key] = (int)$found[0]['codformulariolista']; }
    }
    header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok' => true, 'message' => adm_t('Listas salvas com sucesso.'), 'created' => $created], JSON_UNESCAPED_UNICODE); exit;
}
if ($isAjax && ($_POST['action'] ?? '') === 'delete_row' && ctype_digit((string)($_POST['codformulariolista'] ?? ''))) {
    listaCall($pdo, 'CALL sp_crud_delete(:tabela,:chave)', ['tabela' => 'formulario_lista', 'chave' => listaJson(['codformulariolista' => (int)$_POST['codformulariolista']])]);
    header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok' => true, 'message' => adm_t('Lista excluída com sucesso.')], JSON_UNESCAPED_UNICODE); exit;
}
$gridPage = max(1, (int)($_GET['pagina'] ?? 1)); $gridSize = 25; $gridOffset = ($gridPage - 1) * $gridSize;
$rows = listaCall($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,25,:offset)', ['tabela' => 'vw_formulario_lista_grid', 'filtros' => listaJson([]), 'offset' => $gridOffset]);
$preferenceRows = listaCall($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,100,0)', ['tabela' => 'vw_preferencias_grid', 'filtros' => listaJson(['codusuario' => $uid, 'transacao' => 'seguranca_lista'])]);
$preferences = []; foreach ($preferenceRows as $preference) $preferences[(string)$preference['coluna']] = $preference;
$columns = ['codformulariolista' => adm_t('Código'), 'codigo' => adm_t('Código da lista'), 'label_pt' => adm_t('Label PT'), 'label_en' => adm_t('Label EN'), 'label_es' => adm_t('Label ES'), 'descricao' => adm_t('Descrição'), 'fonte_codigo' => adm_t('Fonte cadastrada'), 'campo_valor' => adm_t('Campo valor'), 'campo_label' => adm_t('Campo label'), 'filtro_json' => adm_t('Filtro'), 'origem' => adm_t('Origem'), 'ativo' => adm_t('Ativo')];
